    # extend existing colored rectangle lines onto all rows/columns flagged by marker
    out=[r[:] for r in grid]
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # marker row fills entire row; marker column fills entire column, preserving marker
    for r,c in marks:
        if c<c0 or c>c1:
            for x in range(w):
                if out[r][x]==0: out[r][x]=2
        elif r<r0 or r>r1:
            for y in range(h):
                if out[y][c]==0: out[y][c]=2
        else:
            # within bounds mark indicates row extension
            for x in range(w):
                if out[r][x]==0: out[r][x]=2
    return out
